test('Interface shift multi-select aligns, duplicates and keyboard undo restores count',async({page})=>{await page.goto('/');await page.getByRole('radio',{name:'Interface',exact:true}).click();await page.getByRole('button',{name:'Create blank document',exact:true}).click();await page.getByRole('button',{name:'Rectangle',exact:true}).first().click();await page.getByRole('button',{name:'Ellipse',exact:true}).first().click();const list=page.getByRole('tree',{name:'Pages and layers',exact:true});await list.getByRole('treeitem',{name:/^Rectangle ·/}).click();await list.getByRole('treeitem',{name:/^Ellipse ·/}).click({modifiers:['Shift']});await expect(page.getByText('2 layers selected',{exact:true}).last()).toBeVisible();await page.getByRole('button',{name:'Left',exact:true}).click();await page.getByRole('button',{name:'Duplicate',exact:true}).click();await expect(page.getByTestId('interface-canvas').locator('[data-testid^="interface-node-"]')).toHaveCount(4);await page.getByTestId('interface-canvas').getByRole('group',{name:/^Ellipse ·/}).last().focus();await page.keyboard.press('Control+z');await expect(page.getByTestId('interface-canvas').locator('[data-testid^="interface-node-"]')).toHaveCount(2);});
